attach.exampleCs:
var libraries = NativeUI.Libraries();
var symbol = libraries.Length > 0 ? libraries[0]["exports"][0] : default;
var button = symbol.IsNull ? null : screen.Root.Attach(symbol);

on.example:
closeLabel.on('press', () => screen.close());
closeLabel.on('rollOver', () => closeLabel.set({ alpha: 1 }));
closeLabel.on('rollOut', () => closeLabel.set({ alpha: 0.7 }));

on.exampleCs:
closeLabel.On("press", new Action(() => screen.Close()));
closeLabel.On("rollOver", new Action(() => closeLabel.Set(new { alpha = 1 })));
closeLabel.On("rollOut", new Action(() => closeLabel.Set(new { alpha = 0.7 })));

setLeading.example:
const list = panel.createText({ x: 40, y: 40, width: 300, height: 280 });
list.setLeading(6);
list.setText('First\nSecond\nThird');

setLeading.exampleCs:
var list = panel.CreateText(new { x = 40, y = 40, width = 300, height = 280 });
list.SetLeading(6);
list.SetText("First\nSecond\nThird");

setTabStops.example:
const table = panel.createText({ x: 40, y: 40, width: 600, height: 200 });
table.setTabStops([0, 220, 400]);
table.setText('Name	Count	Price');

setTabStops.exampleCs:
var table = panel.CreateText(new { x = 40, y = 40, width = 600, height = 200 });
table.SetTabStops(new[] { 0, 220, 400 });
table.SetText("Name	Count	Price");
